330	func redactSessionTranscript(ctx context.Context, transcript []byte) (redact.RedactedBytes, time.Duration, error) {
331		start := time.Now()
332		_, span := perf.Start(ctx, "redact_transcript")
333		defer span.End()
334	
335		if len(transcript) == 0 {
336			return redact.RedactedBytes{}, time.Since(start), nil
337		}
338	
339		redacted, err := redactSessionJSONLBytes(transcript)
340		if err != nil {
341			span.RecordError(err)
342			return redact.RedactedBytes{}, time.Since(start), fmt.Errorf("failed to redact transcript secrets: %w", err)
343		}
344		return redacted, time.Since(start), nil
345	}
