347	// resolveShadowRef returns the shadow branch reference, preferring a pre-resolved
348	// ref when available and falling back to a repo lookup.
349	func resolveShadowRef(repo *git.Repository, branchName string, preResolved *plumbing.Reference) (ref *plumbing.Reference, exists bool) {
350		if preResolved != nil {
351			return preResolved, true
352		}
353		refName := plumbing.NewBranchReferenceName(branchName)
354		resolved, err := repo.Reference(refName, true)
355		if err != nil {
356			return nil, false
357		}
358		return resolved, true
