361	// filterFilesTouched narrows sessionData.FilesTouched to only files present in
362	// committedFiles. When no prior files were recorded (mid-turn commit), it falls
363	// back to the committed set minus Entire metadata paths.
364	func filterFilesTouched(sessionData *ExtractedSessionData, committedFiles map[string]struct{}) {
365		if len(committedFiles) == 0 {
366			return
367		}
368		if len(sessionData.FilesTouched) > 0 {
369			filtered := make([]string, 0, len(sessionData.FilesTouched))
370			for _, f := range sessionData.FilesTouched {
371				if _, ok := committedFiles[f]; ok {
372					filtered = append(filtered, f)
373				}
374			}
375			sessionData.FilesTouched = filtered
376		} else {
377			// Mid-turn commits can happen before SaveStep records FilesTouched.
378			// In that case, fall back to the actual committed files, excluding
379			// Entire's own metadata paths, so the checkpoint still reflects the
380			// files captured by this commit.
381			sessionData.FilesTouched = committedFilesExcludingMetadata(committedFiles)
382		}
383	}
