385	// extractOrCreateSessionData tries to extract session data from the shadow branch,
386	// live transcript, or creates empty session data as a fallback. The empty case is
387	// handled by the skip gate in CondenseSession.
388	func (s *ManualCommitStrategy) extractOrCreateSessionData(ctx context.Context, repo *git.Repository, ag agent.Agent, shadowHash plumbing.Hash, hasShadowBranch bool, state *SessionState) (*ExtractedSessionData, error) {
389		switch {
390		case hasShadowBranch:
391			// Shadow branch exists (from SaveStep commits) — extract transcript and
392			// metadata from the branch tree, preferring the live transcript if fresher.
393			data, err := s.extractSessionData(ctx, repo, shadowHash, state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart, state.Phase.IsActive())
394			if err != nil {
395				return nil, fmt.Errorf("failed to extract session data: %w", err)
396			}
397			return data, nil
398		case state.TranscriptPath != "":
399			// No shadow branch but a live transcript path is known — read directly
400			// from disk. This handles mid-session commits before SaveStep runs.
401			if state.Phase.IsActive() {
402				prepareTranscriptIfNeeded(ctx, ag, state.TranscriptPath)
403			}
404			data, err := s.extractSessionDataFromLiveTranscript(ctx, state)
405			if err != nil {
406				return nil, fmt.Errorf("failed to extract session data from live transcript: %w", err)
407			}
408			return data, nil
409		default:
410			// No shadow branch and no transcript path — create empty session data.
411			// This happens for sessions where the agent never set TranscriptPath
412			// (e.g., Codex hooks may send null transcript_path). The skip gate in
413			// CondenseSession will skip condensation if nothing is found.
414			logging.Debug(logging.WithComponent(ctx, "checkpoint"),
415				"no shadow branch and no transcript path, returning empty session data",
416				slog.String("session_id", state.SessionID),
417				slog.String("agent_type", string(state.AgentType)),
418			)
419			return &ExtractedSessionData{
420				FilesTouched: state.FilesTouched,
421			}, nil
422		}
423	}
