432	// compactAndRedactExternalTranscript calls the external agent's compact-transcript
433	// subcommand and redacts the result. Returns (nil, false) if the agent is not
434	// external. Returns (nil, true) if the agent is external but compaction failed.
435	func compactAndRedactExternalTranscript(ctx context.Context, ag agent.Agent, state *SessionState) (transcript []byte, isExternal bool) {
436		compactor, ok := agent.AsTranscriptCompactor(ag)
437		if !ok {
438			if _, isCap := ag.(agent.CapabilityDeclarer); isCap {
439				logging.Warn(ctx, "external transcript compaction unavailable, skipping transcript.jsonl",
440					slog.String("session_id", state.SessionID),
441					slog.String("agent", string(ag.Name())),
442				)
443				return nil, true
444			}
445			return nil, false
446		}
447	
448		compacted := compactTranscriptForExternalAgent(ctx, compactor, state.SessionID, state.TranscriptPath)
449		if compacted == nil {
450			return nil, true
451		}
452	
453		redacted, err := redactSessionJSONLBytes(compacted.Transcript)
454		if err != nil {
455			logging.Warn(ctx, "failed to redact external compact transcript, dropping",
456				slog.String("session_id", state.SessionID),
457				slog.String("agent", string(compactor.Name())),
458				slog.String("error", err.Error()),
459			)
460			return nil, true
461		}
462		return redacted.Bytes(), true
463	}
