465	// buildExternalCompactTranscript produces the compact transcript for external
466	// agents by calling the agent's compact-transcript subcommand and redacting
467	// the result. Returns nil if the agent is not external (caller should use
468	// buildInternalCompactTranscript instead).
469	func buildExternalCompactTranscript(ctx context.Context, ag agent.Agent, state *SessionState) *compactTranscriptResult {
470		if !settings.IsCheckpointsV2Enabled(ctx) {
471			return nil
472		}
473	
474		compactStart := time.Now()
475		compactCtx, compactSpan := perf.Start(ctx, "compact_transcript_v2")
476		defer compactSpan.End()
477	
478		transcript, isExternal := compactAndRedactExternalTranscript(compactCtx, ag, state)
479		if !isExternal {
480			return nil
481		}
482		if transcript == nil {
483			return &compactTranscriptResult{Duration: time.Since(compactStart)}
484		}
485	
486		startLine := state.CompactTranscriptStart
487		fullLines := countCompactLines(transcript)
488		if fullLines < startLine {
489			logging.Warn(compactCtx, "external compact transcript shorter than previous compact transcript start; resetting compact transcript start",
490				slog.String("session_id", state.SessionID),
491				slog.String("agent", string(ag.Name())),
492				slog.Int("compact_transcript_lines", fullLines),
493				slog.Int("previous_compact_transcript_start", startLine),
494			)
495			startLine = 0
496		}
497	
498		return &compactTranscriptResult{
499			Transcript: transcript,
500			StartLine:  startLine,
501			Duration:   time.Since(compactStart),
502		}
503	}
