505	// buildInternalCompactTranscript produces the compact transcript for built-in
506	// agents from already-redacted transcript bytes.
507	func buildInternalCompactTranscript(ctx context.Context, ag agent.Agent, redacted redact.RedactedBytes, state *SessionState) compactTranscriptResult {
508		if !settings.IsCheckpointsV2Enabled(ctx) {
509			return compactTranscriptResult{}
510		}
511	
512		compactStart := time.Now()
513		compactCtx, compactSpan := perf.Start(ctx, "compact_transcript_v2")
514		defer compactSpan.End()
515	
516		// Generate scoped compact (only new content) for line counting and offset calculation.
517		scopedCompact := compactTranscriptForV2(compactCtx, ag, redacted, state.CheckpointTranscriptStart)
518		// Generate full compact (cumulative) for storage — v2 /main replaces
519		// the session's transcript.jsonl on each write, so we must include all
520		// prior content, not just the new portion.
521		fullCompact := compactTranscriptForV2(compactCtx, ag, redacted, 0)
522		startLine := computeCompactTranscriptStart(compactCtx, ag, state, redacted.Bytes(), scopedCompact)
523	
524		return compactTranscriptResult{
525			Transcript: fullCompact,
526			StartLine:  startLine,
527			Duration:   time.Since(compactStart),
528		}
529	}
