531	func compactTranscriptForExternalAgent(
532		ctx context.Context,
533		compactor agent.TranscriptCompactor,
534		sessionID string,
535		transcriptPath string,
536	) *agent.CompactedTranscript {
537		if transcriptPath == "" {
538			logging.Warn(ctx, "external transcript compaction skipped: missing session transcript path",
539				slog.String("session_id", sessionID),
540				slog.String("agent", string(compactor.Name())),
541			)
542			return nil
543		}
544	
545		compacted, err := compactor.CompactTranscript(ctx, transcriptPath)
546		if err != nil {
547			logging.Warn(ctx, "external transcript compaction failed, skipping transcript.jsonl on /main",
548				slog.String("session_id", sessionID),
549				slog.String("agent", string(compactor.Name())),
550				slog.String("error", err.Error()),
551			)
552			return nil
553		}
554		if compacted == nil {
555			logging.Warn(ctx, "external transcript compaction returned nil transcript",
556				slog.String("session_id", sessionID),
557				slog.String("agent", string(compactor.Name())),
558			)
559			return nil
560		}
561		if len(bytes.TrimSpace(compacted.Transcript)) == 0 {
562			logging.Warn(ctx, "external transcript compaction returned empty transcript",
563				slog.String("session_id", sessionID),
564				slog.String("agent", string(compactor.Name())),
565			)
566			return nil
567		}
568		if !bytes.HasSuffix(compacted.Transcript, []byte{'\n'}) {
569			compacted.Transcript = append(compacted.Transcript, '\n')
570		}
571		if len(compacted.Assets) > 0 {
572			logging.Warn(ctx, "external transcript compaction returned assets that are not yet persisted",
573				slog.String("session_id", sessionID),
574				slog.String("agent", string(compactor.Name())),
575				slog.Int("asset_count", len(compacted.Assets)),
576			)
577		}
578		return compacted
579	}
