581	// generateSummary produces an LLM-generated summary of the session transcript.
582	// The transcript must be pre-redacted to avoid sending secrets to the LLM.
583	// Returns nil if the scoped transcript is empty or generation fails.
584	func generateSummary(ctx context.Context, redactedTranscript redact.RedactedBytes, filesTouched []string, state *SessionState) *cpkg.Summary {
585		summarizeCtx := logging.WithComponent(ctx, "summarize")
586		transcriptBytes := redactedTranscript.Bytes()
587	
588		var scopedTranscript []byte
589		switch state.AgentType {
590		case agent.AgentTypeGemini:
591			scoped, sliceErr := geminicli.SliceFromMessage(transcriptBytes, state.CheckpointTranscriptStart)
592			if sliceErr != nil {
593				logging.Warn(summarizeCtx, "failed to scope Gemini transcript for summary",
594					slog.String("session_id", state.SessionID),
595					slog.String("error", sliceErr.Error()))
596			}
597			scopedTranscript = scoped
598		case agent.AgentTypeOpenCode:
599			scoped, sliceErr := opencode.SliceFromMessage(transcriptBytes, state.CheckpointTranscriptStart)
600			if sliceErr != nil {
601				logging.Warn(summarizeCtx, "failed to scope OpenCode transcript for summary",
602					slog.String("session_id", state.SessionID),
603					slog.String("error", sliceErr.Error()))
604			}
605			scopedTranscript = scoped
606		case agent.AgentTypeCodex, agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeFactoryAIDroid, agent.AgentTypeUnknown:
607			scopedTranscript = transcript.SliceFromLine(transcriptBytes, state.CheckpointTranscriptStart)
608		}
609	
610		if len(scopedTranscript) == 0 {
611			return nil
612		}
613	
614		generator := buildSummaryGenerator(summarizeCtx)
615		// scopedTranscript is sliced from redactedTranscript, which was redacted earlier in CondenseSession.
616		summary, err := summarize.GenerateFromTranscript(summarizeCtx, redact.AlreadyRedacted(scopedTranscript), filesTouched, state.AgentType, generator)
617		if err != nil {
618			logging.Warn(summarizeCtx, "summary generation failed",
619				slog.String("session_id", state.SessionID),
620				slog.String("error", err.Error()))
621			return nil
622		}
623		logging.Info(summarizeCtx, "summary generated",
624			slog.String("session_id", state.SessionID))
625		return summary
626	}
