628	// buildSummaryGenerator returns a Generator based on the configured summary provider.
629	// Returns nil if no provider is configured (GenerateFromTranscript falls back to ClaudeGenerator).
630	//
631	// The return type is the summarize.Generator interface rather than the concrete
632	// adapter pointer so callers can't accidentally hold a non-nil interface that
633	// wraps a nil pointer (the classic Go nil-interface footgun).
634	func buildSummaryGenerator(ctx context.Context) summarize.Generator { //nolint:ireturn // interface return for nil-safety
635		s, err := settings.Load(ctx)
636		if err != nil {
637			// Warn (not Debug): this is the auto-summarize hot path on every commit.
638			// A settings-load failure silently downgrades the user's configured
639			// provider to the default, and Debug would hide that from operators.
640			logging.Warn(ctx, "could not load settings for summary provider, using default",
641				"error", err.Error())
642			return nil
643		}
644		if s.SummaryGeneration == nil || s.SummaryGeneration.Provider == "" {
645			return nil
646		}
647	
648		providerName := types.AgentName(s.SummaryGeneration.Provider)
649		ag, err := agent.Get(providerName)
650		if err != nil {
651			logging.Warn(ctx, "configured summary provider not available, using default",
652				"provider", s.SummaryGeneration.Provider, "error", err.Error())
653			return nil
654		}
655	
656		// Check binary on PATH, not DetectPresence — a repo can use one agent
657		// for development while a different agent generates summaries. Fall back
658		// silently (Warn log) because this runs in the post-commit hook and a
659		// hard error would block the commit.
660		if !agent.IsSummaryCLIAvailable(providerName) {
661			logging.Warn(ctx, "configured summary provider CLI binary not on PATH, using default",
662				"provider", s.SummaryGeneration.Provider)
663			return nil
664		}
665	
666		tg, ok := agent.AsTextGenerator(ag)
667		if !ok {
668			logging.Warn(ctx, "configured summary provider does not support text generation, using default",
669				"provider", s.SummaryGeneration.Provider)
670			return nil
671		}
672	
673		return &summarize.TextGeneratorAdapter{
674			TextGenerator: tg,
675			Model:         summarize.ResolveModel(providerName, s.SummaryGeneration.Model),
676		}
677	}
