679	// marshalPromptAttributionsIncludingPending builds the complete prompt attribution slice
680	// (including PendingPromptAttribution for mid-turn commits) and encodes it to JSON.
681	// This must stay consistent with the slice used by calculateSessionAttributions so the
682	// persisted diagnostics match the computed InitialAttribution.
683	func marshalPromptAttributionsIncludingPending(state *SessionState) json.RawMessage {
684		pas := make([]PromptAttribution, len(state.PromptAttributions), len(state.PromptAttributions)+1)
685		copy(pas, state.PromptAttributions)
686		if state.PendingPromptAttribution != nil {
687			pas = append(pas, *state.PendingPromptAttribution)
688		}
689		if len(pas) == 0 {
690			return nil
691		}
692		data, err := json.Marshal(pas)
693		if err != nil {
694			return nil
695		}
696		return data
697	}
