713	func hasTokenUsageData(usage *agent.TokenUsage) bool {
714		if usage == nil {
715			return false
716		}
717	
718		if usage.InputTokens > 0 || usage.CacheCreationTokens > 0 || usage.CacheReadTokens > 0 || usage.OutputTokens > 0 || usage.APICallCount > 0 {
719			return true
720		}
721	
722		return hasTokenUsageData(usage.SubagentTokens)
723	}
