725	// sessionStateBackfillTokenUsage returns the best session-level token usage to
726	// persist in session state after condensation.
727	func sessionStateBackfillTokenUsage(ctx context.Context, ag agent.Agent, agentType types.AgentType, transcript []byte, checkpointUsage *agent.TokenUsage) *agent.TokenUsage {
728		if agentType == agent.AgentTypeCopilotCLI && len(transcript) > 0 {
729			fullSessionUsage := agent.CalculateTokenUsage(ctx, ag, transcript, 0, "")
730			if hasTokenUsageData(fullSessionUsage) {
731				return fullSessionUsage
732			}
733			logging.Debug(ctx, "copilot-cli: full-session token read produced no data, falling back to checkpoint usage")
734		}
735	
736		if agentType == agent.AgentTypeCopilotCLI && hasTokenUsageData(checkpointUsage) {
737			return checkpointUsage
738		}
739	
740		if checkpointUsage != nil && checkpointUsage.InputTokens > 0 {
741			return checkpointUsage
742		}
743	
744		return nil
745	}
