747	// attributionOpts provides pre-resolved git objects to avoid redundant reads.
748	type attributionOpts struct {
749		headTree              *object.Tree        // HEAD commit tree (already resolved by PostCommit)
750		shadowTree            *object.Tree        // Shadow branch tree (already resolved by PostCommit)
751		parentTree            *object.Tree        // Parent commit tree (nil for initial commits, for consistent non-agent line counting)
752		repoDir               string              // Repository worktree path for git CLI commands
753		parentCommitHash      string              // HEAD's first parent hash (preferred diff base for non-agent files)
754		attributionBaseCommit string              // Base commit hash for non-agent file detection (empty = fall back to go-git tree walk)
755		headCommitHash        string              // HEAD commit hash for non-agent file detection (empty = fall back to go-git tree walk)
