759	func calculateSessionAttributions(ctx context.Context, repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState, opts ...attributionOpts) *cpkg.InitialAttribution {
760		// Calculate initial attribution using accumulated prompt attribution data.
761		// This uses user edits captured at each prompt start (before agent works),
762		// plus any user edits after the final checkpoint (shadow → head).
763		//
764		// When shadowRef is nil (agent committed mid-turn before SaveStep),
765		// HEAD is used as the shadow tree. This is correct because the agent's
766		// commit IS HEAD — there are no user edits between agent work and commit.
767		logCtx := logging.WithComponent(ctx, "attribution")
768	
769		var o attributionOpts
770		if len(opts) > 0 {
771			o = opts[0]
772		}
773	
774		headTree := o.headTree
775		if headTree == nil {
776			headRef, headErr := repo.Head()
777			if headErr != nil {
778				logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
779					slog.String("error", headErr.Error()))
780				return nil
781			}
782	
783			headCommit, commitErr := repo.CommitObject(headRef.Hash())
784			if commitErr != nil {
785				logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
786					slog.String("error", commitErr.Error()))
787				return nil
788			}
789	
790			var treeErr error
791			headTree, treeErr = headCommit.Tree()
792			if treeErr != nil {
793				logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
794					slog.String("error", treeErr.Error()))
795				return nil
796			}
797		}
798	
799		// Get shadow tree: from pre-resolved cache, shadow branch, or HEAD (agent committed directly).
800		shadowTree := o.shadowTree
801		if shadowTree == nil {
802			if shadowRef != nil {
803				shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
804				if shadowErr != nil {
805					logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
806						slog.String("error", shadowErr.Error()),
807						slog.String("shadow_ref", shadowRef.Hash().String()))
808					return nil
809				}
810				var shadowTreeErr error
811				shadowTree, shadowTreeErr = shadowCommit.Tree()
812				if shadowTreeErr != nil {
813					logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
814						slog.String("error", shadowTreeErr.Error()))
815					return nil
816				}
817			} else {
818				// No shadow branch: agent committed mid-turn. Use HEAD as shadow
819				// because the agent's work is the commit itself.
820				logging.Debug(logCtx, "attribution: using HEAD as shadow (no shadow branch)")
821				shadowTree = headTree
822			}
823		}
824	
825		// Get base tree (state before session started)
826		var baseTree *object.Tree
827		attrBase := state.AttributionBaseCommit
828		if attrBase == "" {
829			attrBase = state.BaseCommit // backward compat
830		}
831		if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(attrBase)); baseErr == nil {
832			if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
833				baseTree = tree
834			} else {
835				logging.Debug(logCtx, "attribution: base tree unavailable",
836					slog.String("error", baseTErr.Error()))
837			}
838		} else {
839			logging.Debug(logCtx, "attribution: base commit unavailable",
840				slog.String("error", baseErr.Error()),
841				slog.String("attribution_base", attrBase))
842		}
843	
844		// Include PendingPromptAttribution if it was never moved to PromptAttributions.
845		// This happens when an agent commits mid-turn without calling SaveStep (e.g., Codex).
846		// PendingPromptAttribution is set during UserPromptSubmit but only moved to
847		// PromptAttributions during SaveStep. Without this, mid-turn commits have no PA
848		// data and pre-session worktree dirt cannot be identified for baseline exclusion.
849		promptAttrs := state.PromptAttributions
850		if state.PendingPromptAttribution != nil {
851			promptAttrs = append(promptAttrs, *state.PendingPromptAttribution)
852		}
853	
854		// Log accumulated prompt attributions for debugging
855		var totalUserAdded, totalUserRemoved int
856		for i, pa := range promptAttrs {
857			totalUserAdded += pa.UserLinesAdded
858			totalUserRemoved += pa.UserLinesRemoved
859			logging.Debug(logCtx, "prompt attribution data",
860				slog.Int("checkpoint", pa.CheckpointNumber),
861				slog.Int("user_added", pa.UserLinesAdded),
862				slog.Int("user_removed", pa.UserLinesRemoved),
863				slog.Int("agent_added", pa.AgentLinesAdded),
864				slog.Int("agent_removed", pa.AgentLinesRemoved),
865				slog.Int("index", i))
866		}
867	
868		attribution := CalculateAttributionWithAccumulated(ctx, AttributionParams{
869			BaseTree:              baseTree,
870			ShadowTree:            shadowTree,
871			HeadTree:              headTree,
872			ParentTree:            o.parentTree,
873			FilesTouched:          sessionData.FilesTouched,
874			PromptAttributions:    promptAttrs,
875			RepoDir:               o.repoDir,
876			ParentCommitHash:      o.parentCommitHash,
877			AttributionBaseCommit: attrBase,
878			HeadCommitHash:        o.headCommitHash,
879			AllAgentFiles:         o.allAgentFiles,
880		})
881	
882		if attribution != nil {
883			logging.Info(logCtx, "attribution calculated",
884				slog.Int("agent_lines", attribution.AgentLines),
885				slog.Int("human_added", attribution.HumanAdded),
886				slog.Int("human_modified", attribution.HumanModified),
887				slog.Int("human_removed", attribution.HumanRemoved),
888				slog.Int("total_committed", attribution.TotalCommitted),
889				slog.Float64("agent_percentage", attribution.AgentPercentage),
890				slog.Int("accumulated_user_added", totalUserAdded),
891				slog.Int("accumulated_user_removed", totalUserRemoved),
892				slog.Int("files_touched", len(sessionData.FilesTouched)))
893		}
894	
895		return attribution
896	}
