920	func (s *ManualCommitStrategy) extractSessionData(ctx context.Context, repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType types.AgentType, liveTranscriptPath string, checkpointTranscriptStart int, isActive bool) (*ExtractedSessionData, error) {
921		ag, _ := agent.GetByAgentType(agentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
922		commit, err := repo.CommitObject(shadowRef)
923		if err != nil {
924			return nil, fmt.Errorf("failed to get commit object: %w", err)
925		}
926	
927		tree, err := commit.Tree()
928		if err != nil {
929			return nil, fmt.Errorf("failed to get commit tree: %w", err)
930		}
931	
932		data := &ExtractedSessionData{}
933		// sessionID is already an "entire session ID" (with date prefix)
934		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
935	
936		// Extract transcript — prefer the live file when available, fall back to shadow branch.
937		// The shadow branch copy may be stale if the last turn ended without code changes
938		// (SaveStep is only called when there are file modifications).
939		var fullTranscript string
940		if liveTranscriptPath != "" {
941			// Ensure transcript file exists (OpenCode creates it lazily via `opencode export`).
942			// Only wait for flush when the session is active — for idle/ended sessions the
943			// transcript is already fully flushed (the Stop hook completed the flush).
944			if isActive {
945				prepareTranscriptIfNeeded(ctx, ag, liveTranscriptPath)
946			}
947			if liveData, readErr := os.ReadFile(liveTranscriptPath); readErr == nil && len(liveData) > 0 { //nolint:gosec // path from session state
948				fullTranscript = string(liveData)
949			}
950		}
951		if fullTranscript == "" {
952			// Fall back to shadow branch copy
953			if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
954				if content, contentErr := file.Contents(); contentErr == nil {
955					fullTranscript = content
956				}
957			} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
958				if content, contentErr := file.Contents(); contentErr == nil {
959					fullTranscript = content
960				}
961			}
962		}
963	
964		// Process transcript based on agent type
965		if fullTranscript != "" {
966			data.Transcript = []byte(fullTranscript)
967			data.FullTranscriptLines = countTranscriptItems(agentType, fullTranscript)
968			// Read prompts from shadow branch tree (source of truth after SaveStep)
969			if file, fileErr := tree.File(metadataDir + "/" + paths.PromptFileName); fileErr == nil {
970				if content, contentErr := file.Contents(); contentErr == nil && content != "" {
971					data.Prompts = splitPromptContent(content)
972				}
973			}
974			// Filesystem fallback (written at turn start, covers mid-turn commits)
975			if len(data.Prompts) == 0 {
976				data.Prompts = readPromptsFromFilesystem(ctx, sessionID)
977			}
978		}
979	
980		// Use tracked files from session state (not all files in tree)
981		data.FilesTouched = filesTouched
982	
983		// Calculate token usage from the extracted transcript portion
984		if len(data.Transcript) > 0 {
985			data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, checkpointTranscriptStart, "") //TODO: why do we not use here subagents dir?
986		}
987	
988		return data, nil
989	}
