1029	// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
1030	// For Claude Code and JSONL-based agents, this counts lines.
1031	// For Gemini CLI, OpenCode, and JSON-based agents, this counts messages.
1032	// Returns 0 if the content is empty or malformed.
1033	func countTranscriptItems(agentType types.AgentType, content string) int {
1034		if content == "" {
1035			return 0
1036		}
1037	
1038		// OpenCode uses export JSON format with {"info": {...}, "messages": [...]}
1039		if agentType == agent.AgentTypeOpenCode {
1040			session, err := opencode.ParseExportSession([]byte(content))
1041			if err == nil && session != nil {
1042				return len(session.Messages)
1043			}
1044			return 0
1045		}
1046	
1047		// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
1048		if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
1049			transcript, err := geminicli.ParseTranscript([]byte(content))
1050			if err == nil && transcript != nil && len(transcript.Messages) > 0 {
1051				return len(transcript.Messages)
1052			}
1053			// If agentType is explicitly Gemini but parsing failed, return 0
1054			if agentType == agent.AgentTypeGemini {
1055				return 0
1056			}
1057			// Otherwise fall through to JSONL parsing for Unknown type
1058		}
1059	
1060		// Claude Code and other JSONL-based agents
1061		allLines := strings.Split(content, "\n")
1062		// Trim trailing empty lines (from final \n in JSONL)
1063		for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
1064			allLines = allLines[:len(allLines)-1]
1065		}
1066		return len(allLines)
1067	}
