1069	// extractUserPrompts extracts all user prompts from transcript content.
1070	// Returns prompts with IDE context tags stripped (e.g., <ide_opened_file>).
1071	func extractUserPrompts(agentType types.AgentType, content string) []string {
1072		if content == "" {
1073			return nil
1074		}
1075	
1076		// Droid has its own envelope format — use its parser to normalize first
1077		if agentType == agent.AgentTypeFactoryAIDroid {
1078			lines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes([]byte(content), 0)
1079			if err != nil {
1080				return nil
1081			}
1082			var prompts []string
1083			for _, line := range lines {
1084				if line.Type != transcript.TypeUser {
1085					continue
1086				}
1087				if text := transcript.ExtractUserContent(line.Message); text != "" {
1088					if stripped := textutil.StripIDEContextTags(text); stripped != "" {
1089						prompts = append(prompts, stripped)
1090					}
1091				}
1092			}
1093			return prompts
1094		}
1095	
1096		// OpenCode uses JSONL with a different per-line schema than Claude Code
1097		if agentType == agent.AgentTypeOpenCode {
1098			prompts, err := opencode.ExtractAllUserPrompts([]byte(content))
1099			if err == nil && len(prompts) > 0 {
1100				cleaned := make([]string, 0, len(prompts))
1101				for _, prompt := range prompts {
1102					if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
1103						cleaned = append(cleaned, stripped)
1104					}
1105				}
1106				return cleaned
1107			}
1108			return nil
1109		}
1110	
1111		// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
1112		if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
1113			prompts, err := geminicli.ExtractAllUserPrompts([]byte(content))
1114			if err == nil && len(prompts) > 0 {
1115				// Strip IDE context tags for consistency with Claude Code handling
1116				cleaned := make([]string, 0, len(prompts))
1117				for _, prompt := range prompts {
1118					if stripped := textutil.StripIDEContextTags(prompt); stripped != "" {
1119						cleaned = append(cleaned, stripped)
1120					}
1121				}
1122				return cleaned
1123			}
1124			// If agentType is explicitly Gemini but parsing failed, return nil
1125			if agentType == agent.AgentTypeGemini {
1126				return nil
1127			}
1128			// Otherwise fall through to JSONL parsing for Unknown type
1129		}
1130	
1131		// Claude Code and other JSONL-based agents
1132		return extractUserPromptsFromLines(strings.Split(content, "\n"))
1133	}
