1135	// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
1136	// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
1137	func extractUserPromptsFromLines(lines []string) []string {
1138		var prompts []string
1139		for _, line := range lines {
1140			line = strings.TrimSpace(line)
1141			if line == "" {
1142				continue
1143			}
1144	
1145			var entry map[string]interface{}
1146			if err := json.Unmarshal([]byte(line), &entry); err != nil {
1147				continue
1148			}
1149	
1150			// Check for user message:
1151			// - Claude Code uses "type": "human" or "type": "user"
1152			// - Cursor uses "role": "user"
1153			msgType, _ := entry["type"].(string) //nolint:errcheck // type assertion on interface{} from JSON
1154			msgRole, _ := entry["role"].(string) //nolint:errcheck // type assertion on interface{} from JSON
1155			isUser := msgType == "human" || msgType == "user" || msgRole == "user"
1156			if !isUser {
1157				continue
1158			}
1159	
1160			// Extract message content
1161			message, ok := entry["message"].(map[string]interface{})
1162			if !ok {
1163				continue
1164			}
1165	
1166			// Handle string content
1167			if content, ok := message["content"].(string); ok && content != "" {
1168				cleaned := textutil.StripIDEContextTags(content)
1169				if cleaned != "" {
1170					prompts = append(prompts, cleaned)
1171				}
1172				continue
1173			}
1174	
1175			// Handle array content (e.g., multiple text blocks from VSCode)
1176			if arr, ok := message["content"].([]interface{}); ok {
1177				var texts []string
1178				for _, item := range arr {
1179					if m, ok := item.(map[string]interface{}); ok {
1180						if m["type"] == "text" {
1181							if text, ok := m["text"].(string); ok {
1182								texts = append(texts, text)
1183							}
1184						}
1185					}
1186				}
1187				if len(texts) > 0 {
1188					cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
1189					if cleaned != "" {
1190						prompts = append(prompts, cleaned)
1191					}
1192				}
1193			}
1194		}
1195		return prompts
1196	}
