121	// ReadSession reads a session from Codex's storage (JSONL rollout file).
122	func (c *CodexAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
123		if input.SessionRef == "" {
124			return nil, errors.New("session reference (transcript path) is required")
125		}
126	
127		data, err := os.ReadFile(input.SessionRef)
128		if err != nil {
129			return nil, fmt.Errorf("failed to read transcript: %w", err)
130		}
131	
132		startTime, err := parseSessionStartTime(data)
133		if err != nil {
134			return nil, fmt.Errorf("failed to parse session start time: %w", err)
135		}
136	
137		// Extract modified files from the rollout transcript (best-effort, deduplicated).
138		var modifiedFiles []string
139		seen := make(map[string]struct{})
140		for _, lineData := range splitJSONL(data) {
141			for _, f := range extractFilesFromLine(lineData) {
142				if _, exists := seen[f]; !exists {
143					seen[f] = struct{}{}
144					modifiedFiles = append(modifiedFiles, f)
145				}
146			}
147		}
148	
149		return &agent.AgentSession{
150			SessionID:     input.SessionID,
151			AgentName:     c.Name(),
152			SessionRef:    input.SessionRef,
153			StartTime:     startTime,
154			NativeData:    data,
155			ModifiedFiles: modifiedFiles,
156		}, nil
157	}
