159	// WriteSession writes a session to Codex's storage (JSONL rollout file).
160	func (c *CodexAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
161		if session == nil {
162			return errors.New("session is nil")
163		}
164	
165		if session.AgentName != "" && session.AgentName != c.Name() {
166			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
167		}
168	
169		if session.SessionRef == "" {
170			return errors.New("session reference (transcript path) is required")
171		}
172	
173		if len(session.NativeData) == 0 {
174			return errors.New("session has no native data to write")
175		}
176	
177		dataToWrite := sanitizeRestoredTranscript(session.NativeData)
178		if err := os.WriteFile(session.SessionRef, dataToWrite, 0o600); err != nil {
179			return fmt.Errorf("failed to write transcript: %w", err)
180		}
181	
182		return nil
183	}
