213	func restoredRolloutPath(codexHome, agentSessionID string, startTime time.Time) string {
214		timestamp := startTime.UTC()
215		datePath := filepath.Join(
216			codexHome,
217			timestamp.Format("2006"),
218			timestamp.Format("01"),
219			timestamp.Format("02"),
220		)
221		filename := fmt.Sprintf("rollout-%s-%s.jsonl", timestamp.Format("2006-01-02T15-04-05"), agentSessionID)
222		return filepath.Join(datePath, filename)
223	}
224	
225	func findRolloutBySessionID(codexHome, agentSessionID string) string {
226		if codexHome == "" || validation.ValidateAgentSessionID(agentSessionID) != nil {
227			return ""
228		}
229	
230		patterns := []string{
231			filepath.Join(codexHome, "rollout-*-"+agentSessionID+".jsonl"),
232			filepath.Join(codexHome, "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
233			filepath.Join(filepath.Dir(codexHome), "archived_sessions", "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
234		}
235		for _, pattern := range patterns {
236			matches, err := filepath.Glob(pattern)
237			if err != nil || len(matches) == 0 {
238				continue
239			}
240			// Multiple restored rollouts for the same session ID can exist. Return the
241			// lexicographically latest path so newer dated restores win deterministically.
242			sort.Strings(matches)
243			return matches[len(matches)-1]
244		}
245	
246		return ""
247	}
