16	// HooksFileName is the hooks config file used by Codex.
17	const HooksFileName = "hooks.json"
18	
19	// entireHookPrefixes identifies Entire hook commands.
20	var entireHookPrefixes = []string{
21		"entire ",
22		`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
23	}
