25	// InstallHooks installs Codex hooks in .codex/hooks.json.
26	func (c *CodexAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
27		repoRoot, err := paths.WorktreeRoot(ctx)
28		if err != nil {
29			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests)
30			if err != nil {
31				return 0, fmt.Errorf("failed to get current directory: %w", err)
32			}
33		}
34	
35		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
36	
37		// Read existing hooks.json if present
38		var rawHooks map[string]json.RawMessage
39		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
40		if readErr == nil {
41			var hooksFile map[string]json.RawMessage
42			if err := json.Unmarshal(existingData, &hooksFile); err != nil {
43				return 0, fmt.Errorf("failed to parse existing hooks.json: %w", err)
44			}
45			if hooksRaw, ok := hooksFile["hooks"]; ok {
46				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
47					return 0, fmt.Errorf("failed to parse hooks in hooks.json: %w", err)
48				}
49			}
50		}
51	
52		if rawHooks == nil {
53			rawHooks = make(map[string]json.RawMessage)
54		}
55	
56		// Parse event types we manage
57		var sessionStart, userPromptSubmit, stop []MatcherGroup
58		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
59			return 0, err
60		}
61		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
62			return 0, err
63		}
64		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
65			return 0, err
66		}
67	
68		if force {
69			sessionStart = removeEntireHooks(sessionStart)
70			userPromptSubmit = removeEntireHooks(userPromptSubmit)
71			stop = removeEntireHooks(stop)
72		}
73	
74		// Build hook commands
75		var cmdPrefix string
76		if localDev {
77			cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks codex `
78		} else {
79			cmdPrefix = "entire hooks codex "
80		}
81		sessionStartCmd := cmdPrefix + "session-start"
82		if !localDev {
83			sessionStartCmd = agent.WrapProductionJSONWarningHookCommand(sessionStartCmd, agent.WarningFormatSingleLine)
84		}
85		userPromptSubmitCmd := cmdPrefix + "user-prompt-submit"
86		stopCmd := cmdPrefix + "stop"
87		if !localDev {
88			userPromptSubmitCmd = agent.WrapProductionSilentHookCommand(userPromptSubmitCmd)
89			stopCmd = agent.WrapProductionSilentHookCommand(stopCmd)
90		}
91	
92		count := 0
93	
94		if !hookCommandExists(sessionStart, sessionStartCmd) {
95			sessionStart = addHook(sessionStart, sessionStartCmd)
96			count++
97		}
98		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
99			userPromptSubmit = addHook(userPromptSubmit, userPromptSubmitCmd)
100			count++
101		}
102		if !hookCommandExists(stop, stopCmd) {
103			stop = addHook(stop, stopCmd)
104			count++
105		}
106	
107		if count == 0 {
108			// Still ensure the feature flag is configured even if hooks
109			// were already present (e.g., manually installed).
110			if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
111				return 0, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
112			}
113			return 0, nil
114		}
115	
116		// Marshal modified types back
117		marshalHookType(rawHooks, "SessionStart", sessionStart)
118		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
119		marshalHookType(rawHooks, "Stop", stop)
120	
121		// Preserve existing top-level keys (e.g., $schema) by reusing the parsed file
122		topLevel := make(map[string]json.RawMessage)
123		if readErr == nil {
124			// Re-parse the original file to preserve all top-level keys
125			_ = json.Unmarshal(existingData, &topLevel) //nolint:errcheck // best-effort preservation
126		}
127		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
128		if err != nil {
129			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
130		}
131		topLevel["hooks"] = hooksJSON
132	
133		// Write to file
134		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
135			return 0, fmt.Errorf("failed to create .codex directory: %w", err)
136		}
137	
138		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
139		if err != nil {
140			return 0, fmt.Errorf("failed to marshal hooks.json: %w", err)
141		}
142	
143		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
144			return 0, fmt.Errorf("failed to write hooks.json: %w", err)
145		}
146	
147		// Enable the codex_hooks feature in the project-level .codex/config.toml.
148		// This keeps the feature flag per-repo rather than global.
149		if err := ensureProjectFeatureEnabled(repoRoot); err != nil {
150			return count, fmt.Errorf("failed to enable codex_hooks feature: %w", err)
151		}
152	
153		return count, nil
154	}
