156	// UninstallHooks removes Entire hooks from Codex hooks.json.
157	func (c *CodexAgent) UninstallHooks(ctx context.Context) error {
158		repoRoot, err := paths.WorktreeRoot(ctx)
159		if err != nil {
160			repoRoot = "."
161		}
162	
163		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
164		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
165		if err != nil {
166			return nil //nolint:nilerr // No hooks.json means nothing to uninstall
167		}
168	
169		var topLevel map[string]json.RawMessage
170		if err := json.Unmarshal(data, &topLevel); err != nil {
171			return fmt.Errorf("failed to parse hooks.json: %w", err)
172		}
173	
174		var rawHooks map[string]json.RawMessage
175		if hooksRaw, ok := topLevel["hooks"]; ok {
176			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
177				return fmt.Errorf("failed to parse hooks: %w", err)
178			}
179		}
180		if rawHooks == nil {
181			return nil
182		}
183	
184		var sessionStart, userPromptSubmit, stop []MatcherGroup
185		if err := parseHookType(rawHooks, "SessionStart", &sessionStart); err != nil {
186			return err
187		}
188		if err := parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit); err != nil {
189			return err
190		}
191		if err := parseHookType(rawHooks, "Stop", &stop); err != nil {
192			return err
193		}
194	
195		sessionStart = removeEntireHooks(sessionStart)
196		userPromptSubmit = removeEntireHooks(userPromptSubmit)
197		stop = removeEntireHooks(stop)
198	
199		marshalHookType(rawHooks, "SessionStart", sessionStart)
200		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
201		marshalHookType(rawHooks, "Stop", stop)
202	
203		if len(rawHooks) > 0 {
204			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
205			if err != nil {
206				return fmt.Errorf("failed to marshal hooks: %w", err)
207			}
208			topLevel["hooks"] = hooksJSON
209		} else {
210			delete(topLevel, "hooks")
211		}
212	
213		output, err := jsonutil.MarshalIndentWithNewline(topLevel, "", "  ")
214		if err != nil {
215			return fmt.Errorf("failed to marshal hooks.json: %w", err)
216		}
217		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
218			return fmt.Errorf("failed to write hooks.json: %w", err)
219		}
220		return nil
221	}
