223	// AreHooksInstalled checks if Entire hooks are installed in Codex hooks.json.
224	func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
225		repoRoot, err := paths.WorktreeRoot(ctx)
226		if err != nil {
227			repoRoot = "."
228		}
229	
230		hooksPath := filepath.Join(repoRoot, ".codex", HooksFileName)
231		data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
232		if err != nil {
233			return false
234		}
235	
236		var hooksFile HooksFile
237		if err := json.Unmarshal(data, &hooksFile); err != nil {
238			return false
239		}
240	
241		return hasEntireHook(hooksFile.Hooks.SessionStart) &&
242			hasEntireHook(hooksFile.Hooks.UserPromptSubmit) &&
243			hasEntireHook(hooksFile.Hooks.Stop)
244	}
