247	
248	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]MatcherGroup) error {
249		if data, ok := rawHooks[hookType]; ok {
250			if err := json.Unmarshal(data, target); err != nil {
251				return fmt.Errorf("failed to parse %s hooks: %w", hookType, err)
252			}
253		}
254		return nil
255	}
256	
257	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, groups []MatcherGroup) {
258		if len(groups) == 0 {
259			delete(rawHooks, hookType)
260			return
261		}
262		data, err := jsonutil.MarshalWithNoHTMLEscape(groups)
263		if err != nil {
264			return
265		}
266		rawHooks[hookType] = data
267	}
268	
269	func hookCommandExists(groups []MatcherGroup, command string) bool {
270		for _, group := range groups {
271			for _, hook := range group.Hooks {
272				if hook.Command == command {
273					return true
274				}
275			}
276		}
277		return false
278	}
279	
280	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
281		entry := HookEntry{
282			Type:    "command",
283			Command: command,
284			Timeout: 30,
285		}
286	
287		// Add to an existing group with null matcher, or create a new one
288		for i, group := range groups {
289			if group.Matcher == nil {
290				groups[i].Hooks = append(groups[i].Hooks, entry)
291				return groups
292			}
293		}
294		return append(groups, MatcherGroup{
295			Matcher: nil,
296			Hooks:   []HookEntry{entry},
297		})
298	}
299	
300	func isEntireHook(command string) bool {
301		return agent.IsManagedHookCommand(command, entireHookPrefixes)
302	}
303	
304	func hasEntireHook(groups []MatcherGroup) bool {
305		for _, group := range groups {
306			for _, hook := range group.Hooks {
307				if isEntireHook(hook.Command) {
308					return true
309				}
310			}
311		}
312		return false
313	}
314	
315	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
316		result := make([]MatcherGroup, 0, len(groups))
317		for _, group := range groups {
318			filtered := make([]HookEntry, 0, len(group.Hooks))
319			for _, hook := range group.Hooks {
320				if !isEntireHook(hook.Command) {
321					filtered = append(filtered, hook)
322				}
323			}
324			if len(filtered) > 0 {
325				group.Hooks = filtered
326				result = append(result, group)
327			}
328		}
329		return result
330	}
