903	    tokio::select! {
904	        _ = tokio::time::sleep_until(deadline) => Err(GuardianReviewSessionOutcome::TimedOut),
905	        result = future => Ok(result),
906	        _ = async {
907	            if let Some(cancel_token) = external_cancel {
908	                cancel_token.cancelled().await;
909	            } else {
910	                std::future::pending::<()>().await;
911	            }
912	        } => Err(GuardianReviewSessionOutcome::Aborted),
913	    }
914	}
