// the session has authored file changes — namely, that a prior SaveStep
// recorded a checkpoint. A non-empty transcript by itself is not enough: a
// session can have a transcript and never modify any of the committed files
// (e.g., a read-only review run). Falsely attributing committed files to such
// a session was the original Codex companion bug.
func sessionHasEvidenceOfWork(_ *ExtractedSessionData, state *SessionState) bool {
	return state != nil && state.StepCount > 0
}

