// redactSessionTranscript redacts the transcript once for use by both the compact
// package and the checkpoint stores. Returns the redacted bytes and the duration
// of the redaction operation for perf logging.

input.new_string:
// redactOrDrop runs redactSessionTranscript and, on failure, logs a warning and
// returns empty bytes so the caller can continue with metadata-only writes
// (preserving the long-standing behavior described at the call site). The
// extracted helper keeps CondenseSession's complexity below the maintidx limit.
func redactOrDrop(logCtx context.Context, transcript []byte, sessionID string, checkpointID id.CheckpointID) (redact.RedactedBytes, time.Duration) {
	redactedTranscript, redactDuration, err := redactSessionTranscript(logCtx, transcript)
	if err != nil {
		logging.Warn(logCtx, "failed to redact transcript secrets, dropping transcript for checkpoint",
			slog.String("session_id", sessionID),
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", err.Error()),
		)
		return redact.RedactedBytes{}, redactDuration
	}
	return redactedTranscript, redactDuration
}

// skipIfPostRedactionEmpty is the post-redaction skip gate: it catches sessions
// where the transcript passed the pre-redaction gate (line 165) but ended up
// empty after redaction (e.g., malformed JSONL from an external agent) AND
// there are no FilesTouched left after filterFilesTouched intersected with
// committedFiles. Returns a Skipped CondenseResult when the gate fires; nil
// otherwise. Pairs with the narrowed filterFilesTouched fallback to keep
// metadata-only stubs out of the metadata branch.
func skipIfPostRedactionEmpty(logCtx context.Context, redactedTranscript redact.RedactedBytes, sessionData *ExtractedSessionData, state *SessionState, checkpointID id.CheckpointID, hasShadowBranch bool) *CondenseResult {
	if redactedTranscript.Len() > 0 || len(sessionData.FilesTouched) > 0 {
		return nil
	}
	logging.Info(logCtx, "session skipped: nothing to persist after redaction",
		slog.String("session_id", state.SessionID),
		slog.String("agent_type", string(state.AgentType)),
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Bool("has_shadow_branch", hasShadowBranch),
	)
	return &CondenseResult{
		CheckpointID: checkpointID,
		SessionID:    state.SessionID,
		Skipped:      true,
	}
}

