// filterFilesTouched narrows sessionData.FilesTouched to only files present in
// committedFiles. When no prior files were recorded (mid-turn commit), it falls
// back to the committed set minus Entire metadata paths — but only when there's
// evidence the session actually did work (a transcript was extracted, or a prior
// SaveStep ran). Without that gate, sessions that were registered but never
// produced anything (e.g., ephemeral Codex companion runs that never fire a
// useful Stop hook) would acquire another session's committed files via this
// fallback and write a stub checkpoint with false attribution.
func filterFilesTouched(sessionData *ExtractedSessionData, committedFiles map[string]struct{}, state *SessionState) {
	if len(committedFiles) == 0 {
		return
	}
	if len(sessionData.FilesTouched) > 0 {
		filtered := make([]string, 0, len(sessionData.FilesTouched))
		for _, f := range sessionData.FilesTouched {
			if _, ok := committedFiles[f]; ok {
				filtered = append(filtered, f)
			}
		}
		sessionData.FilesTouched = filtered
		return
	}
	if !sessionHasEvidenceOfWork(sessionData, state) {
		// No prior FilesTouched and no evidence the session produced anything —
		// leave FilesTouched empty so the post-redaction skip gate can drop it.
		return
	}
	// Mid-turn commits can happen before SaveStep records FilesTouched.
	// In that case, fall back to the actual committed files, excluding
	// Entire's own metadata paths, so the checkpoint still reflects the
	// files captured by this commit.
	sessionData.FilesTouched = committedFilesExcludingMetadata(committedFiles)
}

// sessionHasEvidenceOfWork returns true when there is an indication the
// session is a real participant in this commit — either it has prior SaveStep
// activity (StepCount > 0) or it produced a transcript we could read. The
// negative case — neither of those — typically means the session was registered
// at SessionStart but never produced anything (e.g., an ephemeral Codex
// companion session whose hook had a null transcript_path). In that state,
// applying the all-committed-files fallback would attribute another session's
// work to it.
func sessionHasEvidenceOfWork(sessionData *ExtractedSessionData, state *SessionState) bool {
	if len(sessionData.Transcript) > 0 {
		return true
	}
	return state != nil && state.StepCount > 0
}

