// TestHandleLifecycleTurnStart_EphemeralSessionSkipped simulates the Codex
// plugin's ephemeral app-server flow: a session whose hooks fire with
// transcript_path=null. We must not create session state in that case — no
// transcript means we cannot condense, and a registered session would stay
// stuck ACTIVE at every subsequent commit.
func TestHandleLifecycleTurnStart_EphemeralSessionSkipped(t *testing.T) {
	// Cannot use t.Parallel() because we use t.Chdir()
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "init.txt", "init")
	testutil.GitAdd(t, tmpDir, "init.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)
	paths.ClearWorktreeRootCache()

	ag := newMockAgent()
	sessionID := "ephemeral-codex-session"
	event := &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  sessionID,
		SessionRef: "", // ephemeral — no transcript path
		Prompt:     "review this diff",
		Timestamp:  time.Now(),
	}

	require.NoError(t, handleLifecycleTurnStart(context.Background(), ag, event))

	// No session state file should have been created.
	state, err := strategy.LoadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	if state != nil {
		t.Errorf("expected no session state for ephemeral session, got %+v", state)
	}

	// No prompt.txt should have been written either — we skip the whole
	// state-creating path, not just InitializeSession.
	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
	sessionDirAbs, err := paths.AbsPath(context.Background(), sessionDir)
	require.NoError(t, err)
	if _, statErr := os.Stat(filepath.Join(sessionDirAbs, paths.PromptFileName)); !os.IsNotExist(statErr) {
		t.Errorf("expected no prompt.txt for ephemeral session; stat err = %v", statErr)
	}
}

